import { FC, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Form, Input, Modal, ModalProps, Typography } from 'antd';
import { Formik } from 'formik';
import * as Yup from 'yup';

import { useGetUserProfileQuery, useUpdateProfileMutation } from 'entities/User';

interface IProfileEditProps extends ModalProps {
	open: boolean;
	onClose: () => void;
}

export const ProfileEdit: FC<IProfileEditProps> = ({ open, onClose, ...props }) => {
	const { t } = useTranslation();

	const { data } = useGetUserProfileQuery();
	const [updateSettings, { status, isLoading }] = useUpdateProfileMutation();

	const initialValues = { telegram: data?.telegram || '' };

	const validationSchema = Yup.object({
		telegram: Yup.string()
			.trim()
			.required(t('Это поле обязательно для заполнения'))
			.max(64, t('Количество символов не должно превышать {{characters}}', { characters: 64 })),
	});

	useEffect(() => {
		if (status === 'fulfilled') {
			onClose();
		}
	}, [status]); // eslint-disable-line

	return (
		<Modal {...props} width={450} centered open={open} onCancel={onClose} footer={null} destroyOnClose>
			<Flex vertical gap={24}>
				<Typography.Title level={4} style={{ margin: 0 }}>
					{t('Редактирование Telegram-аккаунта')}
				</Typography.Title>

				<Formik
					initialValues={initialValues}
					validationSchema={validationSchema}
					onSubmit={({ telegram }) => {
						updateSettings({ telegram });
					}}>
					{({ values, errors, touched, handleSubmit, getFieldProps }) => {
						return (
							<form onSubmit={handleSubmit}>
								<Flex vertical gap={24}>
									<Form.Item
										label={t('Telegram-аккаунт')}
										layout="vertical"
										validateStatus={errors.telegram && touched.telegram ? 'error' : ''}
										help={errors.telegram && touched.telegram && errors.telegram}>
										<Input placeholder="Telegram-аккаунт" {...getFieldProps('telegram')} disabled={isLoading} />
									</Form.Item>

									<Flex justify="space-between">
										<Button onClick={onClose}>{t('Отменить')}</Button>

										<Button
											type="primary"
											htmlType="submit"
											loading={isLoading}
											disabled={isLoading || !!Object.keys(errors).length || !values.telegram}>
											{t('Сохранить')}
										</Button>
									</Flex>
								</Flex>
							</form>
						);
					}}
				</Formik>
			</Flex>
		</Modal>
	);
};
