import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Card, Flex, Typography } from 'antd';

import { useGetUserProfileQuery } from 'entities/User';

interface IPersonalManagerProps extends HTMLAttributes<HTMLDivElement> {}

export const PersonalManager: FC<IPersonalManagerProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { data } = useGetUserProfileQuery();

	if (!data?.account_manager) {
		return null;
	}

	const {
		account_manager: { first_name, last_name, email },
	} = data;

	return (
		<Card {...props}>
			<Flex vertical gap={8}>
				<Flex vertical>
					<Typography.Text type="secondary">{t('Ваш менеджер')}</Typography.Text>
					{!!(first_name || last_name) && (
						<Typography.Text strong style={{ fontSize: 16 }}>
							{first_name} {last_name}
						</Typography.Text>
					)}
				</Flex>

				{!!email && <Typography.Link href={`mailto:${email}`}>{email}</Typography.Link>}
			</Flex>
		</Card>
	);
};
