import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import DownloadIcon from 'assets/images/icons/download.svg?react';
import { ProfileItem, ProfileSection } from 'entities/User';
import { useGetUserProfileQuery } from 'entities/User/api/api';
import { formatDate } from 'shared/utils';

interface IProfileDocsProps extends HTMLAttributes<HTMLDivElement> {}

export const ProfileDocs: FC<IProfileDocsProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { data } = useGetUserProfileQuery();

	if (!data?.documents.length) {
		return null;
	}

	return (
		<ProfileSection {...props} title={t('Документы')}>
			{data.documents.map((doc) => (
				<ProfileItem
					key={doc.updated_at}
					label={formatDate(new Date(doc.updated_at))}
					value={doc.name}
					link={doc.download_url}
					isDownload
					buttonText={t('Скачать')}
					buttonIcon={<DownloadIcon />}
				/>
			))}
		</ProfileSection>
	);
};
