import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import EditIcon from 'assets/images/icons/edit.svg?react';
import { ProfileItem, ProfileSection } from 'entities/User';
import { useGetUserProfileQuery } from 'entities/User/api/api';

const PASSPORT_URL = import.meta.env.VITE_PASSPORT_URL;

interface IProfileMitgoProps extends HTMLAttributes<HTMLDivElement> {}

export const ProfileMitgo: FC<IProfileMitgoProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { data } = useGetUserProfileQuery();

	return (
		<ProfileSection
			{...props}
			title={t('Настройки Mitgo ID')}
			subtitle={t('Вы будете перенаправлены на страницу My Passport ID')}>
			<ProfileItem
				label={t('Email')}
				value={data?.email}
				link={PASSPORT_URL}
				buttonText={t('Редактировать')}
				buttonIcon={<EditIcon />}
			/>
			<ProfileItem
				label={t('Пароль')}
				value="••••••••••••"
				link={PASSPORT_URL}
				buttonText={t('Редактировать')}
				buttonIcon={<EditIcon />}
			/>
		</ProfileSection>
	);
};
