import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { ReloadOutlined } from '@ant-design/icons';

import { Button } from 'antd';

import { ProfileItem, ProfileSection } from 'entities/User';
import { useGetApiCredentialsQuery, useUpdateApiCredentialsMutation } from 'entities/User/api/api';

const SWAGGER_URL = import.meta.env.VITE_API_SWAGGER_URL;

interface IProfileApiProps extends HTMLAttributes<HTMLDivElement> {}

export const ProfileApi: FC<IProfileApiProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { data } = useGetApiCredentialsQuery();
	const [updateApiCredentials, { isLoading }] = useUpdateApiCredentialsMutation();

	return (
		<ProfileSection {...props} title={t('API')}>
			<div>
				<ProfileItem label={t('Client ID')} value={data?.client_id} withCopy />
				<ProfileItem
					label={t('Client Secret')}
					value={data?.client_secret}
					withCopy
					action={updateApiCredentials}
					isLoading={isLoading}
					buttonText={t('Обновить')}
					buttonIcon={<ReloadOutlined />}
				/>
			</div>

			<Button href={SWAGGER_URL} target="_blank" style={{ marginTop: 12 }}>
				{t('Открыть Swagger')}
			</Button>
		</ProfileSection>
	);
};
