import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import EditIcon from 'assets/images/icons/edit.svg?react';
import { ProfileEdit, ProfileItem, ProfileSection } from 'entities/User';
import { useGetUserProfileQuery } from 'entities/User/api/api';

interface IProfilePersonalProps extends HTMLAttributes<HTMLDivElement> {}

export const ProfilePersonal: FC<IProfilePersonalProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { data } = useGetUserProfileQuery();
	const [editIsOpen, setEditIsOpen] = useState(false);

	return (
		<ProfileSection {...props} title={t('Персональная информация')}>
			<ProfileItem
				label={t('Telegram-аккаунт')}
				value={data?.telegram || '-'}
				action={() => setEditIsOpen(true)}
				buttonText={t('Редактировать')}
				buttonIcon={<EditIcon />}
			/>
			<ProfileEdit open={editIsOpen} onClose={() => setEditIsOpen(false)} />
		</ProfileSection>
	);
};
